 22→type BannerVariantIconProps = Omit<IconProps, 'icon'> & {
 23→  icon?: IconProps['icon'], // Make optional
 24→  variant: BannerVariant,
 25→};
 26→const BannerVariantIcon = ({ variant, ...propsRest }: BannerVariantIconProps) => {
 27→  const icon = ((): IconName => {
 28→    switch (variant) {
 29→      case 'info': return 'info-filled';
 30→      case 'warning': return 'warning-filled';
 31→      case 'error': return 'status-failed-filled';
 32→      case 'success': return 'status-success-filled';
 33→      default: return assertUnreachable(variant);
