 76→export type BannerProps = Omit<ComponentProps<'div'>, 'title'> & {
 77→  /** Whether this component should be unstyled. */
 78→  unstyled?: undefined | boolean,
 79→  
 80→  /** Whether to trim this component (strip any spacing around the element). */
 81→  trimmed?: undefined | boolean,
 82→  
 83→  /** Whether to attempt to display the banner as a single line. */
 84→  compact?: undefined | boolean,
 85→  
 86→  /** Which variant to display, which changes the color and left icon. Defaults to "info". */
 87→  variant?: undefined | BannerVariant,
 88→  
 89→  /** The title of the banner. Optional. */
 90→  title?: undefined | React.ReactNode,
 91→  
 92→  /** If specified, a close action is displayed. Default: false. */
 93→  showCloseAction?: undefined | boolean,
 94→  
 95→  /** Callback that is called when the user requests the banner to close. */
 96→  onClose?: undefined | (() => void),
 97→  
 98→  /** Any additional actions to be shown in the banner. */
 99→  actions?: undefined | React.ReactNode,
100→};
101→/**
102→ * An inline banner that displays a message to the user, usually of a time-sensitive nature.
103→ */
104→export const Banner = Object.assign(
105→  (props: BannerProps) => {
106→    const {
107→      unstyled = false,
108→      trimmed = false,
109→      compact = true,
110→      variant = 'info',
111→      title = '',
112→      showCloseAction = false,
113→      onClose,
114→      actions = null,
115→      children,
116→      ...propsRest
117→    } = props;
118→    
119→    if (showCloseAction && typeof onClose !== 'function') {
120→      console.error(`Missing prop in <Banner/>: 'onClose' function`);
121→    }
122→    
123→    const renderTitle = () => {
124→      if (title) { return title; }
125→      
126→      switch (variant) {
127→        case 'info': return 'Info';
128→        case 'warning': return 'Warning';
129→        case 'error': return 'Error';
130→        case 'success': return 'Success';
131→        default: return assertUnreachable(variant);
132→      }
133→    };
134→    
135→    return (
136→      <div
137→        // Note: `role=alert` implies the banner is time-sensitive. If the banner is not time-sensitive, this may need
138→        // to be overridden with a more appropriate role (depends on use case).
139→        role="alert"
140→        {...propsRest}
141→        className={cx(
142→          'bk',
143→          { [cl['bk-banner']]: !unstyled },
144→          { [cl['bk-banner--trimmed']]: trimmed },
145→          { [cl[`bk-banner--${variant}`]]: variant },
146→          propsRest.className,
147→        )}
148→      >
149→        {/* Apply `bk-theme--light` on all children (but not the box itself). */}
150→        <div className={cx('bk-theme--light', cl['bk-banner__header'])}>
151→          <div className={cx(cl['bk-banner__header__text'])}>
152→            <strong className={cx(cl['bk-banner__title'])}>
153→              <BannerVariantIcon variant={variant} className={cx(cl['bk-banner__title__icon'])}/>
154→              <span className={cx(cl['bk-banner__title__text'])}>{renderTitle()}</span>
155→            </strong>
156→            {compact && children &&
157→              <div className={cx('bk-prose', cl['bk-banner__message--compact'])}>{children}</div>
158→            }
159→          </div>
160→          
161→          <div className={cx(cl['bk-banner__actions'])}>
162→            {actions}
163→            
164→            {showCloseAction &&
165→              <ActionIcon
166→                icon="cross"
167→                label="Close banner"
168→                tooltip={null}
169→                className={cx(cl['bk-banner__action-close'])}
170→                onPress={onClose}
171→              />
172→            }
173→          </div>
174→        </div>
175→        
176→        {!compact && children &&
177→          <article className={cx('bk-prose', 'bk-theme--light', cl['bk-banner__message'])}>{children}</article>
178→        }
179→      </div>
180→    );
181→  },
182→  {
183→    ActionButton,
184→    ActionIcon,
185→  },
186→);
