39→        {...scrollerProps}
40→        {...propsRest}
41→        className={cx(
42→          'bk',
43→          { [cl['bk-panel']]: !unstyled },
44→          { [cl['bk-panel--edgeless']]: !!edgeless },
45→          scrollerProps.className,
46→          propsRest.className,
47→        )}
48→      >
49→        {children}
50→      </section>
51→    );
52→  },
53→  {
54→    Heading: PanelHeading,
55→  },
