31→/**
32→ * Track the current device pixel ratio and store it as a CSS custom property (for use in styling).
33→ * Inspired by: https://frontendmasters.com/blog/obsessing-over-smooth-radial-gradient-disc-edges
34→ */
35→const useDevicePixelRatioTracker = () => {
36→  const [devicePixelRatio, setDevicePixelRatio] = React.useState<number>(window.devicePixelRatio);
37→  
38→  React.useEffect(() => {
39→    document.body.style.setProperty('--bk-device-pixel-ratio', String(devicePixelRatio));
40→    
41→    const controller = new AbortController();
42→    window.matchMedia(`(resolution: ${window.devicePixelRatio}x)`)
43→      .addEventListener('change',
44→        () => { setDevicePixelRatio(window.devicePixelRatio); },
45→        { signal: controller.signal },
46→      );
47→    
48→    return () => { controller.abort(); };
49→  }, [devicePixelRatio]);
50→};
51→
52→export const BaklavaProvider = (props: React.PropsWithChildren) => {
53→  useDevicePixelRatioTracker();
54→  
55→  return (
56→    <TopLayerManager>
57→      <ToastProvider global>
58→        {props.children}
59→      </ToastProvider>
60→    </TopLayerManager>
61→  );
62→};
