 20→export type DialogModalProps = Omit<React.ComponentProps<typeof Dialog>, 'children'> & {
 21→  /** Content of the modal. If a function, will be passed a dialog controller. */
 22→  children?: React.ReactNode | ModalProviderProps['dialog'],
 23→  
 24→  /** Whether this component should be unstyled. */
 25→  unstyled?: undefined | boolean,
 26→  
 27→  /** Whether the modal should be active by default. Default: false. */
 28→  activeDefault?: undefined | boolean,
 29→  
 30→  /** How to display the modal in the viewport. Default: 'center'. */
 31→  display?: undefined | 'center' | 'full-screen' | 'slide-over',
 32→  
 33→  /** If `display` is `slide-over`, from which side the modal should originate. */
 34→  slideOverPosition?: undefined | 'left' | 'right',
 35→  
 36→  /** The size of the modal. Note: does not apply to full screen modals. */
 37→  size?: undefined | 'small' | 'medium' | 'large',
 38→  
 39→  /**
 40→   * A modal trigger to render. Will be passed an `activate` callback to open the modal. Optional, if not specified
 41→   * you can manually trigger the modal through `modalRef` instead.
 42→   */
 43→  trigger?: undefined | ModalProviderProps['children'],
 44→  
 45→  /** Whether to allow users to close the dialog manually. */
 46→  allowUserClose?: undefined | boolean,
 47→  
 48→  /** A reference to the modal, for imperative control. */
 49→  modalRef?: undefined | React.Ref<React.ComponentRef<typeof ModalProvider>>,
 50→  
 51→  /** Any additional props to pass to the modal provider. */
 52→  providerProps?: undefined | Omit<ModalProviderProps, 'children'>,
 53→  
 54→  /** Whether to render the model inline or with in a portal */
 55→  renderMethod?: undefined | ModalProviderProps['renderMethod'],
 56→};
 57→
 58→export type ModalWithSubject<S> = {
 59→  props: Partial<DialogModalProps>,
 60→  subject: undefined | S,
 61→  activateWith: (subject: S | (() => S)) => void,
 62→  deactivate: () => void,
 63→};
 64→/**
 65→ * Utility hook to get a reference to a `DialogModal` for imperative usage. To open, you can call `activate()`, or
 66→ * `activateWith()` if you want to include some subject data to be shown in the modal.
 67→ */
 68→export const useModalWithSubject = <S,>(
 69→  config?: undefined | {
 70→    subjectInitial?: undefined | S | (() => undefined | S),
 71→  },
 72→): ModalWithSubject<S> => {
 73→  const { subjectInitial } = config ?? {};
 74→  
 75→  const modalRef = ModalProvider.useRef();
 76→  const [subject, setSubject] = React.useState<undefined | S>(subjectInitial);
 77→  
 78→  return {
 79→    props: {
 80→      modalRef,
 81→    },
 82→    subject,
 83→    activateWith: (subject: S | (() => S)) => {
 84→      // Use flushSync() to force the modal to render, in case the modal rendering is conditional
 85→      // on the subject being set.
 86→      flushSync(() => { setSubject(subject); });
 87→      
 88→      modalRef.current?.activate();
 89→    },
 90→    deactivate: () => {
 91→      modalRef.current?.deactivate();
 92→    },
 93→  };
 94→};
 95→
 96→/**
 97→ * Similar to `useModalWithSubject`, but will be preconfigured for usage as a confirmation modal.
 98→ */
 99→export const useConfirmationModal = <S,>(
100→  config: {
101→    subjectInitial?: undefined | S | (() => undefined | S),
102→    cancelLabel?: undefined | string,
103→    actionLabel?: undefined | string,
104→    onCancel?: undefined | ((subject: NonUndefined<S>) => void),
105→    onConfirm: (subject: NonUndefined<S>) => void,
106→    cancelActionProps?: undefined | Partial<React.ComponentProps<typeof Dialog.CancelAction>>,
107→    confirmActionProps?: undefined | Partial<React.ComponentProps<typeof Dialog.SubmitAction>>,
108→  },
109→) => {
110→  const {
111→    subjectInitial,
112→    cancelLabel = 'Cancel',
113→    actionLabel = 'Confirm',
114→    onConfirm,
115→    onCancel,
116→    cancelActionProps = {},
117→    confirmActionProps = {},
118→  } = config;
119→  const modal = useModalWithSubject({ subjectInitial });
120→  
121→  const handleConfirm = React.useCallback(() => {
122→    const subject = modal.subject;
123→    if (typeof subject === 'undefined') {
124→      console.error(`Unexpected: missing subject in confirmation`);
125→      return;
126→    }
127→    onConfirm(subject);
128→  }, [modal.subject, onConfirm]);
129→  
130→  const handleCancel = React.useCallback(() => {
131→    const subject = modal.subject;
132→    if (typeof subject === 'undefined') {
133→      console.error(`Unexpected: missing subject in confirmation`);
134→      return;
135→    }
136→    onCancel?.(subject);
137→  }, [modal.subject, onCancel]);
138→  
139→  return {
140→    ...modal,
141→    props: {
142→      ...modal.props,
143→      // A confirmation modal must use the `role="alertdialog"` rather than the default `role="dialog"`.
144→      // See: https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Roles/alertdialog_role
145→      role: 'alertdialog',
146→      display: 'center' as const,
147→      size: 'small' as const,
148→      allowUserClose: false, // Force the user to explicitly select an action
149→      title: 'Confirm',
150→      children: 'Are you sure you want to perform this action?',
151→      actions: (
152→        <>
153→          <Dialog.CancelAction
154→            label={cancelLabel}
155→            {...cancelActionProps}
156→            onPress={mergeCallbacks([cancelActionProps.onPress, handleCancel])}
157→          />
158→          <Dialog.SubmitAction
159→            //autoFocus // Focus "confirm" by default?
160→            label={actionLabel}
161→            {...confirmActionProps}
162→            onPress={mergeCallbacks([cancelActionProps.onPress, handleConfirm])}
163→          />
164→        </>
165→      ),
166→    },
167→  };
168→};
169→
170→/**
171→ * A dialog component displayed as a modal when activating the given trigger.
172→ */
173→export const DialogModal = Object.assign(
174→  (props: DialogModalProps) => {
175→    const {
176→      children,
177→      unstyled = false,
178→      activeDefault = false,
179→      display = 'center',
180→      slideOverPosition = 'right',
181→      size = 'medium',
182→      trigger = () => null,
183→      allowUserClose = true,
184→      modalRef,
185→      providerProps,
186→      renderMethod = 'portal',
187→      ...propsRest
188→    } = props;
189→    
190→    return (
191→      <ModalProvider
192→        activeDefault={activeDefault}
193→        allowUserClose={allowUserClose}
194→        shouldCloseOnBackdropClick={display !== 'full-screen'}
195→        renderMethod={renderMethod}
196→        dialog={dialogController =>
197→          <Dialog
198→            aria-modal="true"
199→            flat={['slide-over'].includes(display)}
200→            {...dialogController.dialogProps}
201→            showCloseIcon={allowUserClose}
202→            autoFocusClose={allowUserClose}
203→            showCancelAction={allowUserClose}
204→            onRequestClose={dialogController.close}
205→            {...propsRest}
206→            className={cx(
207→              'bk',
208→              { [cl['bk-dialog-modal']]: !unstyled },
209→              { [cl['bk-dialog-modal--center']]: display === 'center' },
210→              { [cl['bk-dialog-modal--full-screen']]: display === 'full-screen' },
211→              { [cl['bk-dialog-modal--slide-over']]: display === 'slide-over' },
212→              { [cl['bk-dialog-modal--slide-over--left']]: display === 'slide-over' && slideOverPosition === 'left' },
213→              { [cl['bk-dialog-modal--slide-over--right']]: display === 'slide-over' && slideOverPosition === 'right' },
214→              { [cl['bk-dialog-modal--small']]: size === 'small' },
215→              { [cl['bk-dialog-modal--medium']]: size === 'medium' },
216→              { [cl['bk-dialog-modal--large']]: size === 'large' },
217→              { [cl['bk-dialog-modal--loading']]: propsRest.state === 'loading' },
218→              dialogController.dialogProps.className,
219→              propsRest.className,
220→            )}
221→          >
222→            {typeof children === 'function' ? children(dialogController) : children}
223→          </Dialog>
224→        }
225→        {...providerProps}
226→        ref={mergeRefs(modalRef, providerProps?.ref)}
227→      >
228→        {trigger}
229→      </ModalProvider>
230→    );
231→  },
232→  {
233→    useModalRef: ModalProvider.useRef,
234→    useModalWithSubject,
235→    useConfirmationModal,
236→    Action: Dialog.Action,
237→    ActionIcon: Dialog.ActionIcon,
238→    CancelAction: Dialog.CancelAction,
239→    SubmitAction: Dialog.SubmitAction,
240→  },
241→);
