 54→};
 55→/**
 56→ * A tab component
 57→ */
 58→export const Tabs = (props: TabsProps) => {
 59→  const {
 60→    unstyled = false,
 61→    variant = 'primary',
 62→    orientation = 'horizontal',
 63→    activeKey,
 64→    children,
 65→    onSwitch,
 66→    ...propsRest
 67→  } = props;
 68→  const scrollerProps = useScroller();
 69→
 70→  // Select the activeKey tab among the given list of tabs
 71→  const getActiveTab = (tabs: Array<TabElement>) => {
 72→    const activeTabs = tabs.filter(child => child.props.tabKey === activeKey);
 73→    
 74→    if (activeTabs.length === 0) { return null; }
 75→    if (activeTabs.length > 1) { throw new TypeError(`Ambiguous active tab`); }
 76→    
 77→    return activeTabs[0];
 78→  };
 79→  
 80→  type ActiveTabProps = Omit<TabProps, 'children' | 'tabKey' | 'title' | 'hide' | 'render'>;
 81→  const getActiveTabProps = (tab: TabElement): ActiveTabProps => {
 82→    const { children, tabKey, title, hide, render, tabTriggerProps, ...tabProps } = tab.props;
 83→    return tabProps;
 84→  };
 85→  
 86→  const renderActive = (tab: TabElement) => {
 87→    let tabElement: React.ReactNode;
 88→    if (typeof tab.props.render === 'function') {
 89→      tabElement = tab.props.render();
 90→    } else {
 91→      tabElement = tab.props.children;
 92→    }
 93→    
 94→    return tabElement;
 95→  };
 96→  
 97→  // FIXME: this throws an error in Chromatic, since `child.type` is `undefined`
 98→  // React.Children.forEach(children, (child: React.ReactNode) => {
 99→  //   if (!React.isValidElement(child) || child?.type?.name !== 'Tab') {
100→  //     throw new TypeError(`Expected only children of type Tab, received ${child}: ${JSON.stringify(child?.type)}`);
101→  //   }
102→  // });
103→  
104→  const tabs = React.Children.toArray(children) as Array<TabElement>;
105→  const activeTab = getActiveTab(tabs);
106→  const activeTabProps: null | ActiveTabProps = (activeTab && getActiveTabProps(activeTab)) ?? null;
107→  
108→  return (
109→    <div
110→      {...propsRest}
111→      className={cx(
112→        'bk',
113→        [cl[`bk-tabs--${variant}`]],
114→        [cl[`bk-tabs--${orientation}`]],
115→        { [cl['bk-tabs']]: !unstyled },
116→        propsRest.className,
117→      )}
118→    >
119→      <ul
120→        {...scrollerProps}
121→        className={cx(
122→          cl['bk-tabs__switcher'],
123→          scrollerProps.className
124→        )}
125→        role="tablist"
126→      >
127→        {tabs.map(tab => {
128→          const { tabKey, hide, tabTriggerProps } = tab.props;
129→          
130→          if (hide) { return null; }
131→          
132→          const isActive = tabKey === activeKey;
133→          
134→          return (
135→            <li
136→              key={tabKey}
137→              role="tab"
138→              tabIndex={0}
139→              aria-selected={isActive}
140→              data-tab={tabKey}
141→              {...tabTriggerProps}
142→              className={cx(cl['bk-tabs__switcher__tab'], tabTriggerProps?.className)}
143→              onClick={() => { onSwitch(tab.props.tabKey); }} // FIXME: add a Button and use that instead
144→            >
145→              <span>{tab.props.title}</span>
146→              {/* Hidden duplicated title, used to prevent layout shifts on hover. */}
147→              <span aria-hidden className={cx(cl['bk-tabs__switcher__tab__hover-placeholder'])}>{tab.props.title}</span>
148→            </li>
149→          );
150→        })}
151→      </ul>
152→      
153→      {activeTab &&
154→        <div
155→          role="tabpanel"
156→          {...(activeTabProps ?? {})}
157→          className={cx(
158→            cl['bk-tabs__tab-content'],
159→            activeTabProps?.contentClassName,
160→            activeTabProps?.className
161→          )}
162→        >
163→          {renderActive(activeTab)}
164→        </div>
165→      }
166→    </div>
167→  );
168→};
169→

